-- Expand Baseball with the current Caribbean winter leagues and Basketball
-- with prompt-aware NBA mascots, arenas, retired numbers, and legends.

alter table private.daily_challenge_rounds add column question_prompt text;
alter table private.daily_challenge_rounds add column question_description text;

update private.daily_challenge_rounds r
set question_prompt = case c.category_id
    when 'flags' then 'Which country does this flag belong to?'
    when 'football' then 'Which football identity is this?'
    when 'baseball' then 'Which baseball team is this?'
    when 'basketball' then 'Which NBA team is this?'
    else 'What is this?'
  end,
  question_description = case c.category_id
    when 'flags' then 'Country flag question artwork'
    when 'football' then 'Football identity question artwork'
    when 'baseball' then 'Baseball team identity question artwork'
    when 'basketball' then 'Basketball identity question artwork'
    else 'Quiz question artwork'
  end
from public.daily_challenges c
where c.id = r.challenge_id;

alter table private.daily_challenge_rounds alter column question_prompt set not null;
alter table private.daily_challenge_rounds alter column question_description set not null;
alter table private.daily_challenge_rounds add constraint daily_round_question_prompt_length
  check (char_length(question_prompt) between 1 and 180);
alter table private.daily_challenge_rounds add constraint daily_round_question_description_length
  check (char_length(question_description) between 1 and 200);

alter table private.friend_match_rounds add column question_prompt text;
alter table private.friend_match_rounds add column question_description text;

update private.friend_match_rounds r
set question_prompt = case m.category_id
    when 'flags' then 'Which country does this flag belong to?'
    when 'football' then 'Which football identity is this?'
    when 'baseball' then 'Which baseball team is this?'
    when 'basketball' then 'Which NBA team is this?'
    else 'What is this?'
  end,
  question_description = case m.category_id
    when 'flags' then 'Country flag question artwork'
    when 'football' then 'Football identity question artwork'
    when 'baseball' then 'Baseball team identity question artwork'
    when 'basketball' then 'Basketball identity question artwork'
    else 'Quiz question artwork'
  end
from private.friend_matches m
where m.id = r.match_id;

alter table private.friend_match_rounds alter column question_prompt set not null;
alter table private.friend_match_rounds alter column question_description set not null;
alter table private.friend_match_rounds add constraint friend_round_question_prompt_length
  check (char_length(question_prompt) between 1 and 180);
alter table private.friend_match_rounds add constraint friend_round_question_description_length
  check (char_length(question_description) between 1 and 200);

